                    timeoutSeconds: 1800),
        CommandSpec(name: "model", summary: "Switch a Claude agent's model (/model); answers in seconds with the model it now runs",
                    params: [ParamSpec("target", .string, positional: true, required: true, help: "Agent name (a claude terminal)"),
                             ParamSpec("model", .string, positional: true, required: true, help: "Model alias or id: opus, sonnet, haiku, claude-opus-5-5…"),
                             ParamSpec("wait", .flag, help: "If it is mid-turn, wait for the turn to end instead of refusing"),
                             ParamSpec("timeout", .int, help: "With --wait: seconds to wait for the turn (default 1800)")],
                    timeoutSeconds: 20),
        CommandSpec(name: "ask.result", summary: "Show the reply of an ask sent with --no-wait",
                    params: [ParamSpec("id", .string, positional: true, help: "Ask id (omit to list your recent asks)")], timeoutSeconds: 10),
        CommandSpec(name: "reply", summary: "Answer the ask you were sent (a Cursor's clean reply): its asker gets this text at once",
                    params: [ParamSpec("message", .rest, positional: true, required: true, help: "Your answer to the ask you were sent (≤ 8 KiB)")],
                    timeoutSeconds: 10),
        CommandSpec(name: "open", summary: "Open a http(s)/mailto URL or an installed app (the sandbox's `open`)",
                    params: [ParamSpec("target", .string, positional: true, help: "URL, or an app bundle in /Applications"),
                             ParamSpec("app", .string, help: "Application name or .app (like open -a)")],
                    timeoutSeconds: 20, exposedToMCP: false),
        CommandSpec(name: "check", summary: "Read recent output of an agent",
